class Account:
    def __init__(self, owner):
        self.owner = owner
        self.balance = 0

    def deposit(self, amount):
        self.balance = self.balance + amount

    def withdraw(self, amount):
        if amount > self.balance:
            return "Not enough balance"
        self.balance = self.balance - amount
        return "OK"

acc = Account("Ravi")
acc.deposit(1000)
print(acc.withdraw(300), acc.balance)
print(acc.withdraw(5000), acc.balance)

