class Book:
    def __init__(self, title, author):
        self.title = title
        self.author = author
        self.available = True

    def __str__(self):
        return f"{self.title} by {self.author}"

class Library:
    def __init__(self):
        self.books = []

    def add(self, book):
        self.books.append(book)

    def borrow(self, title):
        for b in self.books:
            if b.title == title and b.available:
                b.available = False
                return True
        return False

    def available_titles(self):
        return sorted(b.title for b in self.books if b.available)
